-- v24_regional_centroformacion.sql
-- Regionales y Centros de Formación del SENA (fuente: directorio oficial 436_2.pdf).
-- Idempotente: usa q-strings + EXCEPTION para ORA-00955/01408 (ya existe).
-- Ejecutar como SEPLOCAL en SQL Developer.

-- Tabla REGIONAL ─────────────────────────────────────────────────────
BEGIN
  EXECUTE IMMEDIATE q'[CREATE TABLE REGIONAL (
    REGIONALID       NUMBER(10)     NOT NULL,
    REGIONALNOMBRE   NVARCHAR2(120) NOT NULL,
    REGIONALACTIVO   NUMBER(1)      DEFAULT 1 NOT NULL,
    CONSTRAINT PK_REGIONAL PRIMARY KEY (REGIONALID)
  )]';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- Tabla CENTROFORMACION ──────────────────────────────────────────────
BEGIN
  EXECUTE IMMEDIATE q'[CREATE TABLE CENTROFORMACION (
    CENTROID         NUMBER(10)     NOT NULL,
    REGIONALID       NUMBER(10)     NOT NULL,
    CENTRONOMBRE     NVARCHAR2(300) NOT NULL,
    CIUDADID         NUMBER(22),
    CENTROACTIVO     NUMBER(1)      DEFAULT 1 NOT NULL,
    CONSTRAINT PK_CENTROFORMACION PRIMARY KEY (CENTROID),
    CONSTRAINT FK_CF_REGIONAL FOREIGN KEY (REGIONALID) REFERENCES REGIONAL(REGIONALID),
    CONSTRAINT FK_CF_CIUDAD   FOREIGN KEY (CIUDADID)   REFERENCES CIUDAD(CIUDADID)
  )]';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE != -955 THEN RAISE; END IF;
END;
/

-- Índices (ORA-01408 = ya está indexada, ORA-00955 = índice ya existe) ─
BEGIN
  EXECUTE IMMEDIATE 'CREATE INDEX IX_CF_REGIONAL ON CENTROFORMACION (REGIONALID)';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE != -955 AND SQLCODE != -1408 THEN RAISE; END IF;
END;
/

BEGIN
  EXECUTE IMMEDIATE 'CREATE INDEX IX_CF_CIUDAD ON CENTROFORMACION (CIUDADID)';
EXCEPTION WHEN OTHERS THEN
  IF SQLCODE != -955 AND SQLCODE != -1408 THEN RAISE; END IF;
END;
/

-- Regionales ─────────────────────────────────────────────────────────

-- Centros de formación ───────────────────────────────────────────────

-- Grants + sinónimos para SEP_APP / SEP_LECTOR ───────────────────────
GRANT SELECT, INSERT, UPDATE, DELETE ON REGIONAL         TO SEP_APP;
GRANT SELECT                         ON REGIONAL         TO SEP_LECTOR;
GRANT SELECT, INSERT, UPDATE, DELETE ON CENTROFORMACION  TO SEP_APP;
GRANT SELECT                         ON CENTROFORMACION  TO SEP_LECTOR;

CREATE OR REPLACE SYNONYM SEP_APP.REGIONAL           FOR SEPLOCAL.REGIONAL;
CREATE OR REPLACE SYNONYM SEP_APP.CENTROFORMACION    FOR SEPLOCAL.CENTROFORMACION;
CREATE OR REPLACE SYNONYM SEP_LECTOR.REGIONAL        FOR SEPLOCAL.REGIONAL;
CREATE OR REPLACE SYNONYM SEP_LECTOR.CENTROFORMACION FOR SEPLOCAL.CENTROFORMACION;

COMMIT;
